// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 blk, address actor) public {
        ts = bound(ts, 2, 1e9);
        blk = bound(blk, 2, 1e9);
        vm.assume(ts != blk);

        // first successful call to initialize pastBlockTime (any block works)
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok0, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok0);

        // move to an arbitrary block where timestamp != block.number
        vm.warp(ts);
        vm.roll(blk);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // General rule: pastBlockTime always records the TIMESTAMP of the call's block
        assertEq(c.pastBlockTime(), ts);
    }
}

