    C c;
    function setUp() public { c = new C{value: 10 ether}(); }
    function testFuzz_property(uint256 ts, uint256 blk, address actor) public {
        ts = bound(ts, 1, type(uint256).max - 1);
        blk = bound(blk, 1, type(uint64).max);
        vm.assume(ts != blk);
        vm.warp(ts);
        vm.roll(blk);
        vm.deal(actor, 10 ether);
