pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount != 10 ether);
        vm.warp(1000);
        vm.deal(actor, amount < 1 ether ? 1 ether : amount);
        bool ok;
        if (amount == 0) {
            vm.prank(actor);
            try c.fallback{}() { ok = true; } catch { ok = false; }
        } else {
            vm.prank(actor);
            try c.fallback{value: amount}() { ok = true; } catch { ok = false; }
        }
        assertTrue(ok == false || amount == 10 ether, "non-10-ether calls must revert");
    }
}

