// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, address actor) public {
        // only non-divisible-by-15 blocks are exercised here (admissible domain kept wide)
        blockNum = bound(blockNum, 1, type(uint64).max);
        vm.assume(blockNum % 15 != 0);
        vm.assume(actor != address(0) && actor != address(c));

        // ensure the timestamp requirement is satisfiable
        vm.warp(1000);
        vm.roll(blockNum);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // general rule: on a block number not divisible by 15, C never pays out,
        // so its balance is still >= the initial 10 ether (nothing was drained).
        assertTrue(address(c).balance >= 10 ether);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }
    function testFuzz_property(uint256 k, address actor) public {
        k = bound(k, 1, 100000);
        vm.assume(actor != address(0) && actor != address(c));
        // land on a block number that is a multiple of 15 (payout condition)
        vm.roll(k * 15);
        // ensure strictly increasing timestamp relative to any past call
        vm.warp(k + 100);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        // general rule: after the payout-due call the contract holds nothing
        assertTrue(address(c).balance == 0);
    }
}
